          if (isCurrent()) {
            pending.delete(key);
            commit(value);
          }
          return value;
        },
        reason => {
          if (isCurrent()) pending.delete(key);
          throw reason;
        }
      );
      token.promise = promise;
      pending.set(key, token);
      return promise;
    },
    get(key) {
      return pending.get(key);
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };

