'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
function deferred() {
  let resolve, reject;
  const promise = new Promise((a, b) => { resolve = a; reject = b; });
  return { promise, resolve, reject };
}

(async () => {
  // 1. Rejections are not cached; all waiters share reason; retry works.
  {
    let calls = 0;
    const reason = { nonError: true };
    const c = createCache({ now: () => 0, load() { calls++; if (calls === 1) throw reason; return 'ok'; } });
    const a = c.get('k'), b = c.get('k');
    await assert.rejects(a, r => r === reason);
    await assert.rejects(b, r => r === reason);
    assert.equal(await c.get('k'), 'ok');
    assert.equal(calls, 2);
  }
  // 2. Old flight settling must not evict newer flight (dedup preserved) nor store.
  {
    const g1 = deferred(), g2 = deferred();
    let calls = 0;
    const c = createCache({ now: () => 0, load() { calls++; return calls === 1 ? g1.promise : g2.promise; } });
    const old = c.get('k'); await tick();
    c.invalidate('k');
    const n1 = c.get('k'); await tick();
    g1.resolve('stale');
    assert.equal(await old, 'stale');
    const n2 = c.get('k');
    g2.resolve('fresh');
    assert.equal(await n1, 'fresh'); assert.equal(await n2, 'fresh');
    assert.equal(calls, 2);
    assert.equal(await c.get('k'), 'fresh');
  }
  // 2b. Old flight rejecting must not evict newer flight.
  {
    const g1 = deferred(), g2 = deferred();
    let calls = 0;
    const c = createCache({ now: () => 0, load() { calls++; return calls === 1 ? g1.promise : g2.promise; } });
    const old = c.get('k'); await tick();
    c.invalidate('k');
    const n1 = c.get('k'); await tick();
    g1.reject('boom');
    await assert.rejects(old, r => r === 'boom');
    const n2 = c.get('k');
    g2.resolve('fresh');
    assert.equal(await n1, 'fresh'); assert.equal(await n2, 'fresh');
    assert.equal(calls, 2);
  }
  // 3. set wins over earlier load; TTL not restarted; expiry starts new load.
  {
    let t = 0; const g = deferred(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load() { calls++; return calls === 1 ? g.promise : 'new'; } });
    const old = c.get('k'); await tick();
    c.set('k', 'set');
    t = 5; g.resolve('stale');
    assert.equal(await old, 'stale');
    assert.equal(await c.get('k'), 'set');
    t = 10;
    assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'new');
    assert.equal(calls, 2);
  }
  // 4. Repeated invalidations with no stored value are separate barriers.
  {
    const gs = [deferred(), deferred(), deferred()]; let calls = 0;
    const c = createCache({ now: () => 0, load() { return gs[calls++].promise; } });
    const a = c.get('k'); await tick();
    c.invalidate('k');
    const b = c.get('k'); await tick();
    c.invalidate('k');
    const d = c.get('k'); await tick();
    gs[0].resolve(1); gs[1].resolve(2); gs[2].resolve(3);
    assert.deepEqual(await Promise.all([a, b, d]), [1, 2, 3]);
    assert.equal(await c.get('k'), 3);
    assert.equal(calls, 3);
  }
  // 5. clear detaches all flights.
  {
    const g = deferred(); let calls = 0;
    const c = createCache({ now: () => 0, load(k) { calls++; return calls === 1 ? g.promise : 'fresh-' + k; } });
    const a = c.get('x'); await tick();
    c.clear(); g.resolve('stale');
    assert.equal(await a, 'stale');
    assert.equal(await c.get('x'), 'fresh-x');
  }
  // 6. load invalidates/sets own key synchronously; reads own key without await joins.
  {
    let calls = 0; let joined;
    const c = createCache({ now: () => 0, load(k) {
      calls++;
      if (calls === 1) { joined = c.get(k); c.invalidate(k); return 'first'; }
      return 'second';
    } });
    assert.equal(await c.get('k'), 'first');
    assert.equal(await joined, 'first');
    assert.equal(await c.get('k'), 'second');
    assert.equal(calls, 2);

    let calls2 = 0;
    const c2 = createCache({ now: () => 0, load(k) { calls2++; if (calls2 === 1) c2.set(k, 'manual'); return 'loaded'; } });
    assert.equal(await c2.get('k'), 'loaded');
    assert.equal(await c2.get('k'), 'manual');
    assert.equal(calls2, 1);
  }
  // 7. ttlMs=0 dedups unsettled flight, never reuses settled value; undefined values.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, ttlMs: 0, load() { calls++; return undefined; } });
    const [a, b] = await Promise.all([c.get('k'), c.get('k')]);
    assert.equal(a, undefined); assert.equal(b, undefined); assert.equal(calls, 1);
    await c.get('k'); assert.equal(calls, 2);
    assert.equal(c.size, 0);
  }
  console.log('all scenarios ok');
})().catch(e => { console.error(e); process.exit(1); });

